<script setup>
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import FileUpload from '../components/FileUpload.vue';
import api from '../services/api';
import { useAuthStore } from '../stores/auth';
import { useRoute } from 'vue-router';
import { RouterLink } from 'vue-router';
import { savedAcademicTerm, saveAcademicTerm, academicTermLabel, semesterLabel } from '../services/academic-term';
const auth=useAuthStore(),admin=computed(()=>auth.user?.role==='ADMIN');
const route=useRoute(),termFilter=ref(String(route.query.termId||savedAcademicTerm(auth.user?.id)||'')),subjectFilter=ref(String(route.query.subjectId||'')),sectionFilter=ref(''),facultyFilter=ref('');
watch(termFilter,value=>saveAcademicTerm(auth.user?.id,value));
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const meetings=ref([]),offerings=ref([]),rooms=ref([]),terms=ref([]),sections=ref([]),attachments=ref([]),attachmentUrls=ref({}),selectedFile=ref(null),localPreview=ref(''),uploadProgress=ref(0),viewer=ref(null),replacingId=ref(null),loading=ref(true),saving=ref(false),exporting=ref(''),error=ref(''),notice=ref('');
const attachmentForm=ref({title:'',description:'',termId:'',audience:'ALL',sectionId:'',offeringId:''});
const blankMeeting=()=>({offeringId:'',roomId:'',weekday:1,startTime:'08:00',endTime:'09:00',effectiveStart:'',effectiveEnd:''});
const form=ref(blankMeeting()),editingId=ref(null);
function displayTime(time){const [hour,minute]=String(time).split(':').map(Number);return `${hour%12||12}:${String(minute).padStart(2,'0')} ${hour>=12?'PM':'AM'}`;}
const today=computed(()=>{const value=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Manila',weekday:'long'}).format(new Date());return days.indexOf(value)+1;});
const visibleMeetings=computed(()=>meetings.value.filter(item=>(!termFilter.value||String(item.termId)===String(termFilter.value))&&(!subjectFilter.value||String(item.subjectId)===String(subjectFilter.value))&&(!sectionFilter.value||String(item.sectionId)===String(sectionFilter.value))&&(!facultyFilter.value||String(item.facultyId)===String(facultyFilter.value))));
const selectedTerm=computed(()=>terms.value.find(term=>String(term.id)===String(termFilter.value)));
const emptyScheduleMessage=computed(()=>selectedTerm.value?.semester==='SECOND'&&selectedTerm.value?.academicYear==='2026–2027'?'No classes scheduled for Second Semester, AY 2026–2027.':'No scheduled classes for this selection.');
const termDraft=ref({academicYear:'',semester:'FIRST',startDate:'',endDate:''});
const termDates=ref({termId:'',startDate:'',endDate:''});
watch(()=>termDates.value.termId,value=>{const term=terms.value.find(item=>String(item.id)===String(value));termDates.value.startDate=term?.startDate||'';termDates.value.endDate=term?.endDate||'';});
async function createTerm(){if(saving.value)return;saving.value=true;error.value='';try{await api.post('/academic/terms',{...termDraft.value,startDate:termDraft.value.startDate||null,endDate:termDraft.value.endDate||null});notice.value='Academic term created. It is not activated automatically.';termDraft.value={academicYear:'',semester:'FIRST',startDate:'',endDate:''};await load();}catch(e){error.value=e.response?.data?.message||'Could not create academic term.';}finally{saving.value=false;}}
async function updateTermDates(){if(saving.value||!termDates.value.termId)return;saving.value=true;error.value='';try{await api.patch(`/academic/terms/${termDates.value.termId}`,{startDate:termDates.value.startDate||null,endDate:termDates.value.endDate||null});notice.value='Academic term dates updated.';await load();}catch(e){error.value=e.response?.data?.message||'Could not update academic term dates.';}finally{saving.value=false;}}
const scheduleSubjects=computed(()=>[...new Map(meetings.value.map(meeting=>[meeting.subjectId,meeting])).values()]);
const scheduleSections=computed(()=>[...new Map(meetings.value.map(meeting=>[meeting.sectionId,meeting])).values()]);
const scheduleFaculty=computed(()=>[...new Map(meetings.value.filter(meeting=>meeting.facultyId).map(meeting=>[meeting.facultyId,meeting])).values()]);
function saveBlob(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function downloadSchedule(format){if(exporting.value||!termFilter.value)return;exporting.value=format;error.value='';notice.value='';try{
  const params={termId:termFilter.value,subjectId:subjectFilter.value||undefined,sectionId:admin.value&&sectionFilter.value||undefined,facultyId:admin.value&&facultyFilter.value||undefined};
  const stem=`sbaa-schedule-${terms.value.find(t=>String(t.id)===String(termFilter.value))?.academicYear||'term'}-snapshot`;
  const first=await api.get(`/schedule/export/${format}`,{params,responseType:'blob'});
  if(format==='jpg'){const count=Math.max(1,Number(first.headers['x-schedule-pages']||1));saveBlob(first.data,`${stem}-1-of-${count}.jpg`);for(let page=2;page<=count;page++){const result=await api.get('/schedule/export/jpg',{params:{...params,page},responseType:'blob'});saveBlob(result.data,`${stem}-${page}-of-${count}.jpg`);}notice.value=`Downloaded ${count} timetable image${count===1?'':'s'}.`;}
  else{saveBlob(first.data,`${stem}.${format}`);notice.value='Schedule snapshot downloaded.';}
}catch(e){let message='Could not export schedule. Check the term and filters.';if(e.response?.data instanceof Blob&&e.response.data.type.includes('json')){try{message=JSON.parse(await e.response.data.text()).message||message;}catch{}}error.value=message;}finally{exporting.value='';}}
async function load(){loading.value=true;error.value='';try{const requests=[api.get('/schedule/meetings'),api.get('/schedule-attachments'),api.get('/academic/terms')];if(admin.value)requests.push(api.get('/academic/offerings'),api.get('/schedule/rooms'),api.get('/academic/sections'));const results=await Promise.all(requests);meetings.value=results[0].data.data;attachments.value=results[1].data.data;terms.value=results[2].data.data;if(admin.value){offerings.value=results[3].data.data;rooms.value=results[4].data.data;sections.value=results[5].data.data;if(!attachmentForm.value.termId)attachmentForm.value.termId=terms.value.find(t=>t.isCurrent)?.id||terms.value[0]?.id||'';}for(const value of Object.values(attachmentUrls.value))URL.revokeObjectURL(value);attachmentUrls.value={};await Promise.all(attachments.value.slice(0,30).map(loadAttachmentImage));}catch(e){error.value=e.response?.data?.message||'Could not load schedule.';}finally{loading.value=false;}}
async function loadAttachmentImage(item){try{const result=await api.get(`/schedule-attachments/${item.id}/image`,{responseType:'blob'});attachmentUrls.value[item.id]=URL.createObjectURL(result.data);}catch{}}
function chooseFile(file){if(!file)return;error.value='';if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){error.value='Choose a PNG, JPEG, or WebP image up to 5 MB.';return;}if(localPreview.value)URL.revokeObjectURL(localPreview.value);selectedFile.value=file;localPreview.value=URL.createObjectURL(file);}
function dropFile(event){event.preventDefault();chooseFile(event.dataTransfer?.files?.[0]);}
function removeFile(){selectedFile.value=null;if(localPreview.value)URL.revokeObjectURL(localPreview.value);localPreview.value='';replacingId.value=null;}
async function saveAttachment(){if(saving.value||!selectedFile.value)return;saving.value=true;error.value='';uploadProgress.value=0;try{const data=new FormData();if(!replacingId.value){for(const [key,value] of Object.entries(attachmentForm.value))data.append(key,String(value));}data.append('image',selectedFile.value);await api[replacingId.value?'put':'post'](replacingId.value?`/schedule-attachments/${replacingId.value}/image`:'/schedule-attachments',data,{onUploadProgress:event=>{if(event.total)uploadProgress.value=Math.round(event.loaded*100/event.total);}});notice.value=replacingId.value?'Replacement saved as draft.':'Schedule image saved as draft.';removeFile();await load();}catch(e){error.value=e.response?.data?.message||'Could not save schedule image. Retry after checking the file.';}finally{saving.value=false;}}
async function changeAttachment(item,status){if(!window.confirm(`${status==='PUBLISHED'?'Publish':'Archive'} “${item.title}”?`))return;saving.value=true;try{await api.patch(`/schedule-attachments/${item.id}/status`,{status});notice.value=status==='PUBLISHED'?'Schedule image published.':'Schedule image archived.';await load();}catch(e){error.value=e.response?.data?.message||'Could not update attachment.';}finally{saving.value=false;}}
function prepareReplacement(item){replacingId.value=item.id;selectedFile.value=null;if(localPreview.value)URL.revokeObjectURL(localPreview.value);localPreview.value='';document.getElementById('attachment-form')?.scrollIntoView({behavior:'smooth'});}
async function downloadAttachment(item){try{const result=await api.get(`/schedule-attachments/${item.id}/image?download=true`,{responseType:'blob'});const url=URL.createObjectURL(result.data),link=document.createElement('a');link.href=url;link.download=`sbaa-schedule-${item.id}.webp`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=e.response?.data?.message||'Could not download image.';}}
function onViewerKey(event){if(event.key==='Escape')viewer.value=null;}
document.addEventListener('keydown',onViewerKey);
onBeforeUnmount(()=>{document.removeEventListener('keydown',onViewerKey);removeFile();for(const value of Object.values(attachmentUrls.value))URL.revokeObjectURL(value);});
async function save(){saving.value=true;error.value='';try{if(editingId.value)await api.put(`/schedule/meetings/${editingId.value}`,form.value);else await api.post('/schedule/meetings',form.value);notice.value='Class meeting saved.';editingId.value=null;form.value=blankMeeting();await load();}catch(e){error.value=e.response?.data?.message||'Could not save class meeting.';}finally{saving.value=false;}}
function edit(meeting){editingId.value=meeting.id;form.value={offeringId:meeting.offeringId,roomId:meeting.roomId,weekday:meeting.weekday,startTime:meeting.startTime,endTime:meeting.endTime,effectiveStart:meeting.effectiveStart||'',effectiveEnd:meeting.effectiveEnd||''};document.getElementById('schedule-form')?.scrollIntoView({behavior:'smooth'});}
async function cancelOccurrence(meeting){const occurrenceDate=window.prompt(`Cancel a ${days[meeting.weekday-1]} occurrence of ${meeting.subjectCode}. Enter its date (YYYY-MM-DD):`);if(!occurrenceDate)return;const reason=window.prompt('Reason for cancelling this class occurrence:');if(!reason?.trim())return;saving.value=true;error.value='';try{await api.post(`/schedule/meetings/${meeting.id}/exceptions`,{occurrenceDate,reason:reason.trim()});notice.value='Class occurrence cancelled. Affected students and faculty were notified.';}catch(e){error.value=e.response?.data?.message||'Could not cancel this occurrence.';}finally{saving.value=false;}}
async function addRoom(event){const code=event.target.elements.roomCode.value,name=event.target.elements.roomName.value;saving.value=true;error.value='';try{await api.post('/schedule/rooms',{code,name});event.target.reset();notice.value='Room created.';await load();}catch(e){error.value=e.response?.data?.message||'Could not add room.';}finally{saving.value=false;}}
async function archive(meeting){if(!window.confirm(`Archive ${meeting.subjectCode} on ${days[meeting.weekday-1]}?`))return;saving.value=true;try{await api.patch(`/schedule/meetings/${meeting.id}/archive`);notice.value='Meeting archived.';await load();}catch(e){error.value=e.response?.data?.message||'Could not archive meeting.';}finally{saving.value=false;}}
onMounted(load);
</script>
<template><PortalLayout title="Schedule"><div class="dashboard content-page"><div class="page-heading"><div><p class="eyebrow">ASIA/MANILA LOCAL TIME</p><h2>{{admin?'Class schedule':'My weekly schedule'}}</h2><p>Recurring meetings are shown by local weekday and time.</p></div></div>
  <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p><p v-if="loading" class="empty">Loading schedule…</p>
  <template v-else><section class="panel"><div class="toolbar"><label>Academic term<select v-model="termFilter"><option value="">All terms</option><option v-for="term in terms" :key="term.id" :value="term.id">{{academicTermLabel(term)}}</option></select></label><label>Subject<select v-model="subjectFilter"><option value="">All subjects</option><option v-for="subject in scheduleSubjects" :key="subject.subjectId" :value="subject.subjectId">{{subject.subjectCode}} — {{subject.subject}}</option></select></label><label v-if="admin">Section<select v-model="sectionFilter"><option value="">All sections</option><option v-for="section in scheduleSections" :key="section.sectionId" :value="section.sectionId">{{section.section}}</option></select></label><label v-if="admin">Faculty<select v-model="facultyFilter"><option value="">All faculty</option><option v-for="faculty in scheduleFaculty" :key="faculty.facultyId" :value="faculty.facultyId">{{faculty.faculty}}</option></select></label><div class="schedule-export-actions" role="group" aria-label="Download schedule snapshot"><button class="secondary-button" :disabled="!termFilter||!!exporting||!selectedTerm?.startDate||!selectedTerm?.endDate" @click="downloadSchedule('ics')">Calendar (.ics)</button><button class="secondary-button" :disabled="!termFilter||!!exporting" @click="downloadSchedule('jpg')">Timetable image (.jpg)</button><button class="secondary-button" :disabled="!termFilter||!!exporting" @click="downloadSchedule('xlsx')">Excel workbook (.xlsx)</button></div></div><p class="field-help">Select an academic term to download the filtered schedule. Downloads are one-time snapshots, not live sync. {{exporting?`Preparing ${exporting.toUpperCase()}…`:''}}</p><p v-if="selectedTerm&&!selectedTerm.startDate" class="field-help">Term dates are not configured. You can plan classes, but calendar downloads, date-based reminders, and occurrence controls are unavailable until an administrator sets the dates.</p></section><section class="panel"><h2>Weekly schedule</h2><div v-if="visibleMeetings.length" class="week-grid"><div v-for="(day,index) in days" :key="day" class="day-column" :class="{today:today===index+1}"><h3>{{day}}<span v-if="today===index+1">Today</span></h3><div v-for="meeting in visibleMeetings.filter(m=>m.weekday===index+1)" :key="meeting.id" class="class-card"><strong>{{displayTime(meeting.startTime)}}–{{displayTime(meeting.endTime)}} (Asia/Manila)</strong><h4>{{meeting.subjectCode}}</h4><p>{{meeting.subject}}</p><small>Room {{meeting.room}} · {{meeting.section}}</small><small v-if="meeting.effectiveStart||meeting.effectiveEnd">Effective {{meeting.effectiveStart||'term start'}} to {{meeting.effectiveEnd||'term end'}}</small><div v-if="admin"><button class="text-button" :disabled="saving" @click="edit(meeting)">Edit</button><button class="text-button" :disabled="saving" @click="cancelOccurrence(meeting)">Cancel occurrence</button><button class="text-button" :disabled="saving" @click="archive(meeting)">Archive</button></div></div><p v-if="!visibleMeetings.some(m=>m.weekday===index+1)" class="empty">No class</p></div></div><div v-else class="empty"><p>{{emptyScheduleMessage}}</p><a v-if="admin&&selectedTerm&&offerings.some(o=>String(o.termId)===String(selectedTerm.id))" href="#schedule-form" class="secondary-button">Schedule a class</a><RouterLink v-else-if="admin&&selectedTerm" :to="`/admin/subjects?termId=${selectedTerm.id}`" class="secondary-button">Create a class assignment</RouterLink></div></section>
  <section v-if="admin" class="panel"><h2>Academic term management</h2><p class="field-help">Create a future term without activating it. Dates may be set later; existing classes, enrollments, and grades stay with their original term.</p><div class="two-panel"><form class="stack-form" @submit.prevent="createTerm"><h3>Add academic term</h3><label>Academic year (for example 2027–2028)<input v-model="termDraft.academicYear" required placeholder="2027–2028"/></label><label>Semester<select v-model="termDraft.semester"><option value="FIRST">First Semester</option><option value="SECOND">Second Semester</option><option value="SUMMER">Summer</option></select></label><div class="two-fields"><label>Start date (optional)<input v-model="termDraft.startDate" type="date"/></label><label>End date (optional)<input v-model="termDraft.endDate" type="date"/></label></div><button class="primary" :disabled="saving">Create term</button></form><form class="stack-form" @submit.prevent="updateTermDates"><h3>Set term dates</h3><label>Term<select v-model="termDates.termId" required><option value="" disabled>Select term</option><option v-for="term in terms" :key="term.id" :value="term.id">{{academicTermLabel(term)}}</option></select></label><div class="two-fields"><label>Start date<input v-model="termDates.startDate" type="date"/></label><label>End date<input v-model="termDates.endDate" type="date"/></label></div><button class="secondary-button" :disabled="saving||!termDates.termId">Save dates</button></form></div></section>
  <div v-if="admin" class="two-panel"><section id="schedule-form" class="panel"><h2>{{editingId?'Edit class meeting':'Schedule a class'}}</h2><form class="stack-form" @submit.prevent="save"><label>Class assignment<select v-model="form.offeringId" required><option value="" disabled>Select class assignment</option><option v-for="o in offerings" :key="o.id" :value="o.id">{{o.code}} — Section {{o.section}} — {{semesterLabel(o.semester)}} · AY {{o.academicYear}} — {{o.faculty||'Teacher pending'}}</option></select></label><label>Room<select v-model="form.roomId" required><option value="" disabled>Select room</option><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.code}} · {{r.name}}</option></select></label><label>Day<select v-model.number="form.weekday"><option v-for="(day,index) in days" :key="day" :value="index+1">{{day}}</option></select></label><div class="two-fields"><label>Starts (Asia/Manila)<input v-model="form.startTime" type="time" required/></label><label>Ends (Asia/Manila)<input v-model="form.endTime" type="time" required/></label></div><div class="two-fields"><label>Effective from (optional; term start by default)<input v-model="form.effectiveStart" type="date"/></label><label>Effective until (optional; term end by default)<input v-model="form.effectiveEnd" type="date"/></label></div><p class="field-help">Enrolled students and the assigned teacher receive one in-app reminder up to 15 minutes before each active class occurrence.</p><button class="primary" :disabled="saving">{{saving?'Saving…':editingId?'Update class meeting':'Save class meeting'}}</button><button v-if="editingId" type="button" class="text-button" @click="editingId=null">Cancel edit</button></form></section><section class="panel"><h2>Add room</h2><form class="stack-form" @submit.prevent="addRoom"><label>Room code<input name="roomCode" required maxlength="40"/></label><label>Room name<input name="roomName" required maxlength="120"/></label><button class="primary" :disabled="saving">{{saving?'Saving…':'Add room'}}</button></form></section></div>
  <section class="panel"><h2>Schedule publications</h2><p class="subtle">Images supplement the verified class meetings above; they do not change the timetable.</p><div v-if="attachments.length" class="attachment-grid"><article v-for="item in attachments" :key="item.id" class="attachment-card"><img v-if="attachmentUrls[item.id]" :src="attachmentUrls[item.id]" :alt="item.description" loading="lazy"/><div><span class="role-badge">{{item.status}} · {{item.audience}} · v{{item.version}}</span><h3>{{item.title}}</h3><p>{{item.description}}</p><small>{{item.author}} · {{new Date(item.updatedAt).toLocaleDateString('en-PH',{timeZone:'Asia/Manila'})}}</small><div class="inline-actions"><button class="text-button" @click="viewer=item">Enlarge</button><button class="text-button" @click="downloadAttachment(item)">Download</button><template v-if="admin"><button v-if="item.status!=='ARCHIVED'" class="text-button" @click="prepareReplacement(item)">Replace</button><button v-if="item.status==='DRAFT'" class="text-button" @click="changeAttachment(item,'PUBLISHED')">Publish</button><button v-if="item.status!=='ARCHIVED'" class="text-button" @click="changeAttachment(item,'ARCHIVED')">Archive</button></template></div></div></article></div><p v-else class="empty">No schedule images have been published for your classes.</p></section>
  <section v-if="admin" id="attachment-form" class="panel narrow-panel"><h2>{{replacingId?'Replace schedule image':'Add schedule image'}}</h2><p class="field-help">PNG, JPEG, or WebP, up to 5 MB. Images are checked and converted before storage.</p><form class="stack-form" @submit.prevent="saveAttachment"><template v-if="!replacingId"><label>Title<input v-model="attachmentForm.title" required maxlength="180"/></label><label>Description for accessibility<textarea v-model="attachmentForm.description" required maxlength="1000" rows="3"/></label><label>Term<select v-model="attachmentForm.termId" required><option value="" disabled>Select term</option><option v-for="term in terms" :key="term.id" :value="term.id">{{term.academicYear}} · {{term.semester}}</option></select></label><label>Audience<select v-model="attachmentForm.audience"><option value="ALL">All portal users</option><option value="SECTION">One section</option><option value="OFFERING">One class assignment</option></select></label><label v-if="attachmentForm.audience==='SECTION'">Section<select v-model="attachmentForm.sectionId" required><option value="" disabled>Select section</option><option v-for="section in sections" :key="section.id" :value="section.id">{{section.program}} · {{section.name}}</option></select></label><label v-if="attachmentForm.audience==='OFFERING'">Class assignment<select v-model="attachmentForm.offeringId" required><option value="" disabled>Select class assignment</option><option v-for="offering in offerings.filter(o=>o.termId==attachmentForm.termId)" :key="offering.id" :value="offering.id">{{offering.code}} · {{offering.section}}</option></select></label></template><FileUpload :file="selectedFile" :preview="localPreview" :max-mb="5" :busy="saving&&!!selectedFile" :progress="uploadProgress" label="Choose schedule image or photo" hint="PNG, JPEG, or WebP from files or photo library." @select="chooseFile" @remove="removeFile"/><button class="primary" :disabled="saving||!selectedFile">{{saving?'Saving…':replacingId?'Save replacement as draft':'Save image as draft'}}</button><button v-if="replacingId" type="button" class="text-button" @click="removeFile">Cancel replacement</button></form></section></template><div v-if="viewer" class="image-viewer" role="dialog" aria-modal="true" :aria-label="viewer.title" @click.self="viewer=null"><div><button class="secondary-button" @click="viewer=null">Close image</button><img :src="attachmentUrls[viewer.id]" :alt="viewer.description"/><p>{{viewer.title}} — {{viewer.description}}</p></div></div></div></PortalLayout></template>
